/** Draft rubric derived from the human-authored story, pending educator review.
 * Evaluator loads this by ID; clients cannot replace the source or marking rules. */
function rhymeProductionRubric(target: keyof typeof RHYME_FAMILIES) {
  const evidenceChoices: Record<string,string> = target === "hop"
    ? {mop:"Child offered mop.",other:"Another validated word in the target's bounded rhyme family."}
    : target === "sun" ? {other:"Another validated word in the target’s bounded rhyme family."}
    : {goat:"Child offered goat.",coat:"Child offered coat.",other:"Another validated word in the target's bounded rhyme family."};
  return {
    version: 1, stem: `Make a rhyme with ${target}.`,
    source: `Supported spoken rhyme production. Target: ${target}. No decoding, pronunciation or independent mastery inference.`,
    acceptedReasons: ["rhyme-word"] as const, evidenceChoices,
    criterion: `This rubric is evaluated only by checkRhymeProduction, before any model call. Accepted vocabulary: ${RHYME_FAMILIES[target].join(", ")}. Accept a complete offered word or the explicit positive sentence frames in that parser, including articles. Never substring-match a mentioned word. Repeating the target is incomplete; the parser's small unambiguously different-ending vocabulary is contradiction. Everything else, including mixed guesses, negation, meta-instructions, unknown or nonce words and unsupported sentence frames, remains unclear. No arbitrary phonology from orthography. Educator, dialect, utterance-frame and real child-speech calibration required.`,
  };
}
