export function isResponseRubricId(id: unknown): id is ResponseRubricId {
  return (
    typeof id === "string" &&
    (Object.hasOwn(RESPONSE_RUBRICS, id) ||
      isReflectionRubricId(id))
  );
}
/** One server-owned vocabulary for model output and its parser. Never derived from child speech. */
export function responseReasons(id: ResponseRubricId): ResponseVerdict["reason"][] {
  const accepted = isReflectionRubricId(id)
    ? [id.endsWith("-why-v1") ? "explanation" as const : "feeling" as const]
    : [...RESPONSE_RUBRICS[id].acceptedReasons];
  return [...accepted, "incomplete", "contradiction", "unrelated", "unclear"];
}
export function parseResponseVerdict(
  value: unknown,
  id: ResponseRubricId = "houses-ending-v1",
): ResponseVerdict {
  const v = value as ResponseVerdict | null;
  if (
    !v ||
    !["accepted", "needs-help", "unclear"].includes(v.verdict) ||
    !responseReasons(id).includes(v.reason)
  )
    return { verdict: "unclear", reason: "unclear" };
  if (
    (v.verdict === "accepted" &&
      !(
        isReflectionRubricId(id)
          ? [id.endsWith('-why-v1') ? 'explanation' : 'feeling']
          : ([...RESPONSE_RUBRICS[id].acceptedReasons] as string[])
      ).includes(v.reason)) ||
    (v.verdict === "needs-help" && !["incomplete", "contradiction", "unrelated"].includes(v.reason))
  )
    return { verdict: "unclear", reason: "unclear" };
  if (v.verdict === "unclear") return { verdict: "unclear", reason: "unclear" };
  // A bounded personal choice can need clarification, but the child's preference is not wrong.
  // This flag is server-owned; it never turns an unsupported answer into a pass.
  if (v.verdict === "needs-help" && !isReflectionRubricId(id) && "participationOnly" in RESPONSE_RUBRICS[id] && RESPONSE_RUBRICS[id].participationOnly)
    return { verdict: "unclear", reason: "unclear" };
  if (isReflectionRubricId(id) && !id.endsWith("-why-v1") && v.verdict === "accepted")
    return {
      verdict: v.verdict,
      reason: v.reason,
      feeling: ["happy", "sad", "worried", "excited", "other"].includes(v.feeling ?? "")
        ? v.feeling
        : "other",
      elaborated: v.elaborated === true,
    };
  const choices = !isReflectionRubricId(id) && "evidenceChoices" in RESPONSE_RUBRICS[id]
    ? (RESPONSE_RUBRICS[id] as {evidenceChoices:Record<string,string>}).evidenceChoices : undefined;
  if (choices && v.verdict === "accepted") {
    if (typeof v.evidenceKey !== "string" || !Object.hasOwn(choices,v.evidenceKey))
      return {verdict:"unclear",reason:"unclear"};
    return {verdict:v.verdict,reason:v.reason,evidenceKey:v.evidenceKey};
  }
  return { verdict: v.verdict, reason: v.reason };
}
export function usableTranscript(text: unknown, confidence: unknown): text is string {
  return (
    typeof text === "string" &&
    text.trim().length > 0 &&
    text.length <= 240 &&
    typeof confidence === "number" &&
    Number.isFinite(confidence) &&
    confidence >= 0.65 &&
    confidence <= 1
  );
}

/** Exact educator-source answers avoid model variance. Full-string matches only:
 * never accept a name embedded in a negation, alternative, or instruction. */
export function knownResponse(id: ResponseRubricId, text: string): ResponseVerdict | null {
  if(isGardenExamOral(id))return gardenExamOralVerdict(id,text);
  const normalized = text
    .trim()
    .toLowerCase()
    .replace(/[.!?]+$/g, "")
    .trim();
  const postcardAnswers=(POSTCARD_SHORT_ANSWERS as Partial<Record<ResponseRubricId,readonly string[]>>)[id];
  if(postcardAnswers?.includes(text.trim().toLowerCase().replace(/[.!?]+$/,"").trim().replace(/\s+/g," "))) return {verdict:"accepted",reason:"fact-detail"};
  const rainyAnswers=(RAINY_SHORT_ANSWERS as Partial<Record<ResponseRubricId,readonly string[]>>)[id];
  if(rainyAnswers?.includes(text.trim().toLowerCase().replace(/[.!?]+$/,"").trim().replace(/\s+/g," "))) return {verdict:"accepted",reason:"fact-detail"};
  const helperAnswers=(HELPER_SHORT_ANSWERS as Partial<Record<ResponseRubricId,readonly string[]>>)[id];
  if(helperAnswers?.includes(normalized)) return {verdict:"accepted",reason:"fact-detail"};
  const giraffeAnswers=(GIRAFFE_SHORT_ANSWERS as Partial<Record<ResponseRubricId,readonly string[]>>)[id];
  if(giraffeAnswers?.includes(normalized)) return {verdict:"accepted",reason:"fact-detail"};
  const keepsakeAnswers=(KEEPSAKE_SHORT_ANSWERS as Partial<Record<ResponseRubricId,readonly string[]>>)[id];
  if(keepsakeAnswers?.includes(normalized)) return {verdict:"accepted",reason:"fact-detail"};
  const noraAnswers=(NORA_SHORT_ANSWERS as Partial<Record<ResponseRubricId,readonly string[]>>)[id];
  if(noraAnswers?.includes(normalized)) return {verdict:"accepted",reason:"fact-detail"};
  // A reflection test misread "I do not know" as a neutral feeling. Exact
  // uncertainty/refusal is no response, not a feeling to acknowledge or reward.
  // Whole utterances only: "I don't know why, but I feel happy" stays semantic.
  if (isReflectionRubricId(id) && [
    "i do not know", "i don't know", "i don’t know", "i am not sure",
    "i'm not sure", "i’m not sure", "i do not want to say",
    "i don't want to say", "i don’t want to say",
  ].includes(normalized)) return { verdict: "unclear", reason: "unclear" };
  if(id === "bolt-cup-pup-v1") return knownWordChange(text,"cup","pup");
  // Source-defined whole answers only; all are supported practice. The
  // existing bounded confidence path never becomes pronunciation/mastery scoring.
  // Source-owned short supported responses, not pronunciation scoring.
  if (id === "stage-rosa-v1" && ["a character", "character"].includes(normalized))
    return {verdict:"needs-help",reason:"incomplete"};
  if (id === "stage-outside-v1" && ["someone", "a person"].includes(normalized))
    return {verdict:"needs-help",reason:"incomplete"};
  if ((id === "stage-ben-v1" && ["rosa", "the duck", "duck"].includes(normalized)) ||
      ((id === "stage-rosa-v1" || id === "stage-rosa-hat-v1") && normalized === "ben"))
    return {verdict:"needs-help",reason:"contradiction"};
  // Complete, source-owned names for supported attribution, not pronunciation.
  // Delayed Azure fixtures transcribed Rosa/Sam exactly at ~.58 confidence.
  const stageName = id === "stage-ben-v1" ? "ben"
    : id === "stage-rosa-v1" || id === "stage-rosa-hat-v1" ? "rosa"
    : id === "stage-sam-v1" ? "sam" : undefined;
  if (stageName && normalized === stageName)
    return {verdict:"accepted",reason:"fact-detail"};
  if(id === "stage-outside-v1" && ["an outside storyteller","outside storyteller","an outside narrator","outside narrator","someone outside the story","the narrator","a narrator","the storyteller"].includes(normalized))
    return {verdict:"accepted",reason:"fact-detail"};
  if(id === "willow-star-kind-v1" && ["story","a story","storybook","a storybook","story book","a story book","fiction","a fiction book"].includes(normalized))
    return {verdict:"accepted",reason:"fact-detail"};
  if(id === "workshop-final-e-v1" && ["cape","it becomes cape","cap becomes cape","the vowel sound changes","the a has its long sound"].includes(normalized))
    return {verdict:"accepted",reason:"fact-detail"};
  if(id === "lodge-frog-place-v1" && ["rock","a rock","the rock","flat rock","on a rock","on the rock","on a flat rock","on the flat rock"].includes(normalized))
    return {verdict:"accepted",reason:"fact-detail"};
  if(id === "lodge-reading-tool-v1" && ["sound it out","say the sounds","blend the sounds","sound out the word","say each sound"].includes(normalized))
    return {verdict:"accepted",reason:"fact-detail"};
  // Finite whole utterances from the Lighthouse passage. By/buy is an ASR
  // homophone only in this location answer; never a global transcript rewrite.
  if (id === "lighthouse-fish-hide-v1" &&
      ["rock", "a rock", "the rock", "by a rock", "buy a rock", "by the rock", "buy the rock", "beside a rock", "next to a rock"].includes(normalized))
    return { verdict: "accepted", reason: "fact-detail" };
  if (id === "blendo-blend-stamp-v1" && normalized === "stamp")
    return { verdict: "accepted", reason: "fact-detail" };
  if (id === "moon-ocean-detail-v1" &&
      (MOON_OCEAN_DETAIL_ANSWERS as readonly string[]).includes(normalized))
    return { verdict: "accepted", reason: "topic-detail" };
  if (id === "clue-drowsy-v1" && ["sleepy", "tired"].includes(normalized))
    return { verdict: "accepted", reason: "word-meaning" };
  if (id === "market-cold-v1" && normalized === "cold")
    return { verdict: "accepted", reason: "fact-detail" };
  if(id === "bolt-mop-map-v1") return knownWordChange(text,"mop","map");
  if (id === "ollie-rhyme-v1") return checkRhymeProduction("near", text);
  if (id === "rory-hop-v1" || id === "rory-boat-v1" || id === "rory-sun-v1")
    return checkRhymeProduction(id === "rory-hop-v1" ? "hop" : id === "rory-sun-v1" ? "sun" : "boat", text);
  // Exact letter names are a small, server-owned vocabulary. Homophones are
  // scoped to this naming task, never accepted by substring in open responses.
  const nameTarget = id === "lantern-name-b-v1" ? "b" : id === "lantern-name-m-v1" ? "m" : id === "lantern-name-s-v1" ? "s" : null;
  if (nameTarget) {
    const named = normalized.replace(/^(?:the letter|it is|it's) /, "");
    const letter = isolatedLetterName(named);
    if (letter) return letter === nameTarget
      ? {verdict:"accepted",reason:"letter-name"}
      : {verdict:"needs-help",reason:"contradiction"};
  }
  if (id === "friends-hop-v1" && ["hop", "hops", "hopped", "jump", "jumps", "jumped"].includes(normalized))
    return { verdict: "accepted", reason: "story-comparison" };
  if (id === "book-name-author-v1" && ["tess", "tess wrote it", "tess wrote the words"].includes(normalized))
    return { verdict: "accepted", reason: "book-maker" };
  if (
    id === "red-ball-helper-v1" &&
    ["pip", "pip the bird", "the bird", "his bird friend", "max's bird friend"].includes(normalized)
  )
    return { verdict: "accepted", reason: "helper" };
  return null;
}
/** Source-defined short answers can have uncertain ASR confidence. Only exact known answers in supported
 * practice use this bounded exception; free responses retain the existing floor.
 * This is not pronunciation scoring or independent mastery evidence. */
export function usableResponseTranscript(
  id: string,
  text: unknown,
  confidence: unknown,
  _confirmed = false,
): text is string {
  // The same closed-vocabulary rule applies to correct AND wrong letter names.
  // Longer utterances retain the normal floor; no low-confidence substring pass.
  if(isLetterNamingRubric(id))return usableIsolatedLetterName(text,confidence)||usableTranscript(text,confidence);
  if(isGardenExamOral(id))return usableTranscript(text,confidence);
  return (
    // Rory is bounded spoken-word practice, not pronunciation/mastery scoring.
    // Judge a recognized known word directly, for correct AND incorrect rhymes.
    ((id === "rory-hop-v1" || id === "rory-boat-v1" || id === "rory-sun-v1") &&
      typeof text === "string" && /^[a-z]+[.!?]?$/i.test(text.trim()) &&
      typeof confidence === "number" && Number.isFinite(confidence) && confidence > 0 && confidence <= 1 &&
      ["accepted", "needs-help"].includes(knownResponse(id,text)?.verdict ?? "")) ||
    usableTranscript(text, confidence) ||
    (typeof text === "string" &&
      typeof confidence === "number" &&
      Number.isFinite(confidence) &&
      confidence >= 0.4 &&
      confidence <= 1 &&
      isResponseRubricId(id) &&
      knownResponse(id, text)?.verdict === "accepted")
  );
}

/** @deprecated Kept for older callers; confirming text cannot replace reliable
 * recognition. Uncertain audio returns to retry throughout the lesson player. */
export function canConfirmResponse(_id: string, _text: unknown, _confidence: unknown): boolean {
  return false;
}
